page.script:
function CrrHandler(t) {
	if (t.id == "bnew") {
		var serverWin = Ext.getCmp("serverWin");
		if (serverWin == null) {
			Ext.Msg.wait("请求正在提交中,请等候...", "请求", "...");
			Ext.Ajax.request({
				url : "getContent",
				method : "POST",
				params: {menuCode: "TextForm"},
				success : function(response, options) {
					Ext.Msg.hide();
					var res = $.parseJSON(response.responseText);
					eval(res.data);
				},
				failure: function(form, action) {
					Ext.MessageBox.alert("警告", action.result.errors);
				}
			});
		}
	}
}
